#[inline]
const fn dbcc_mask(bits: u32) -> u64 {
    if bits >= 64 { u64::MAX } else { (1u64 << bits) - 1u64 }
}

#[inline]
fn dbcc_extract(payload: u64, start: u32, bits: u32, motorola: bool) -> u64 {
    let lane = if motorola { payload.swap_bytes() } else { payload };
    (lane >> start) & dbcc_mask(bits)
}

#[inline]
fn dbcc_insert(payload: &mut u64, start: u32, bits: u32, motorola: bool, value: u64) {
    let mask = dbcc_mask(bits);
    let mut lane = if motorola { payload.swap_bytes() } else { *payload };
    lane = (lane & !(mask << start)) | ((value & mask) << start);
    *payload = if motorola { lane.swap_bytes() } else { lane };
}

