pub static ALL_MESSAGES: &[MessageInfo] = &[
    MessageInfo { id: CAN_ID_SDOPCU, dlc: CAN_DLC_SDOPCU, name: "SDOPCU", is_extended: false, cycle_time_ms: None, signals: SIGNALS_SDOPCU },
    MessageInfo { id: CAN_ID_SDOMCU, dlc: CAN_DLC_SDOMCU, name: "SDOMCU", is_extended: false, cycle_time_ms: None, signals: SIGNALS_SDOMCU },
];

/// Return metadata for every CAN message in the DBC.
pub const fn get_all_mess() -> &'static [MessageInfo] { ALL_MESSAGES }

pub fn get_message(id: u32) -> Option<&'static MessageInfo> {
    ALL_MESSAGES.iter().find(|message| message.id == id)
}

pub fn get_all_signals(id: u32) -> Option<&'static [SignalInfo]> {
    get_message(id).map(|message| message.signals)
}

pub fn get_signal(id: u32, name: &str) -> Option<&'static SignalInfo> {
    get_all_signals(id)?.iter().find(|signal| signal.name == name)
}

pub fn message_dlc(id: u32) -> Option<u8> { get_message(id).map(|m| m.dlc) }

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Message {
    Sdopcu(Sdopcu),
    Sdomcu(Sdomcu),
}

impl Message {
    pub const fn id(&self) -> u32 {
        match self {
            Self::Sdopcu(_) => Sdopcu::ID,
            Self::Sdomcu(_) => Sdomcu::ID,
        }
    }

    pub const fn dlc(&self) -> u8 {
        match self {
            Self::Sdopcu(_) => Sdopcu::DLC,
            Self::Sdomcu(_) => Sdomcu::DLC,
        }
    }

    pub const fn payload(&self) -> u64 {
        match self {
            Self::Sdopcu(message) => message.payload(),
            Self::Sdomcu(message) => message.payload(),
        }
    }

    pub const fn frame(&self) -> CanFrame {
        CanFrame { id: self.id(), dlc: self.dlc(), payload: self.payload() }
    }

    pub const fn get_sdopcu(&self) -> Option<&Sdopcu> {
        match self { Self::Sdopcu(message) => Some(message), _ => None }
    }

    pub fn get_sdopcu_mut(&mut self) -> Option<&mut Sdopcu> {
        match self { Self::Sdopcu(message) => Some(message), _ => None }
    }

    pub const fn get_sdomcu(&self) -> Option<&Sdomcu> {
        match self { Self::Sdomcu(message) => Some(message), _ => None }
    }

    pub fn get_sdomcu_mut(&mut self) -> Option<&mut Sdomcu> {
        match self { Self::Sdomcu(message) => Some(message), _ => None }
    }

}

pub fn decode_message(id: u32, payload: u64, dlc: u8) -> Result<Message, DbccError> {
    match id {
        CAN_ID_SDOPCU => {
            if dlc != CAN_DLC_SDOPCU {
                return Err(DbccError::InvalidDlc { id, expected: CAN_DLC_SDOPCU, actual: dlc });
            }
            Ok(Message::Sdopcu(Sdopcu::from_payload(payload)))
        }
        CAN_ID_SDOMCU => {
            if dlc != CAN_DLC_SDOMCU {
                return Err(DbccError::InvalidDlc { id, expected: CAN_DLC_SDOMCU, actual: dlc });
            }
            Ok(Message::Sdomcu(Sdomcu::from_payload(payload)))
        }
        _ => Err(DbccError::UnknownMessage { id }),
    }
}

#[repr(u8)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SdoOpcode {
    GetReq = 1, SetReq = 2, GetAllReq = 3, Response = 128,
    ErrOutOfRange = 253, ErrWriteReadOnly = 254, Error = 255,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SdoStatus { Ok, UnknownVariable, ReadOnly, NoValue, OutOfRange, TxMissing, BadFrame }

pub type SdoTxCallback = fn(u32, u8, u64) -> bool;
pub type SdoValueHook = fn(u32, u16);

pub fn sdo_frame(id: u32, opcode: SdoOpcode, var_id: u16, raw: u64, bits: u32) -> CanFrame {
    let mut payload = 0u64;
    dbcc_insert(&mut payload, 0, 8, false, opcode as u64);
    dbcc_insert(&mut payload, 8, 10, false, var_id as u64);
    dbcc_insert(&mut payload, 24, bits, false, raw);
    CanFrame { id, dlc: 7, payload }
}

