    pub fn set_pcu_t_0_batt(&mut self, value: f32) -> bool {
        self.send(CAN_ID_SDOPCU, SdoOpcode::SetReq, 4u16, sdo_encode_pcu_t_0_batt(value), 32u32)
    }

    /// Non-destructive getter for the latest received value.
