    pub fn request_mcu(&mut self, var: McuVar) -> bool {
        if var as u16 != 0 && !self.mcu.hash_verified { return false; }
        self.send(CAN_ID_SDOMCU, SdoOpcode::GetReq, var as u16, 0, var.bit_length())
    }

    /// Request every variable from this SDO slave.
