    pub fn get_all_mcu(&mut self) -> bool { self.request_all_mcu() }

    pub const fn has_mcu_value(&self, var: McuVar) -> bool {
        match var {
            McuVar::DbcHash => self.mcu.has_new_dbc_hash,
            McuVar::IsPosTorqueAllowed => self.mcu.has_new_is_pos_torque_allowed,
            McuVar::IsNegTorqueAllowed => self.mcu.has_new_is_neg_torque_allowed,
            McuVar::MotorMaxTorque => self.mcu.has_new_motor_max_torque,
            McuVar::LimPosTorque => self.mcu.has_new_lim_pos_torque,
            McuVar::LimNegTorque => self.mcu.has_new_lim_neg_torque,
            McuVar::LimRpm => self.mcu.has_new_lim_rpm,
            McuVar::SpeedLimitation => self.mcu.has_new_speed_limitation,
            McuVar::ScsActive => self.mcu.has_new_scs_active,
            McuVar::ScsMonitorBmsLv => self.mcu.has_new_scs_monitor_bmslv,
            McuVar::ScsMonitorBmsHv => self.mcu.has_new_scs_monitor_bmshv,
            McuVar::ScsMonitorEbs => self.mcu.has_new_scs_monitor_ebs,
            McuVar::SerialCoreUsb => self.mcu.has_new_serial_core_usb,
        }
    }

